  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "اپنے لکھے ہوئے چند پیراگراف پیسٹ کریں — کوئی ای میل، میسج، کچھ بھی جو آپ کے قدرتی انداز میں ہو۔",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "آپ کا مطلب اور حقائق بالکل ویسے ہی رکھتا ہے — صرف پڑھنے کا انداز بدلتا ہے۔ تحریر کا نمونہ اختیاری ہے مگر سب سے بڑا فرق اسی سے پڑتا ہے۔",
  "Rewritten": "دوبارہ لکھا گیا",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "روکھا یا AI جیسا ٹیکسٹ پیسٹ کریں، اپنی تحریر کا نمونہ شامل کریں، اور یہ آپ کے انداز میں واپس آتا ہے — وہی مطلب، انسانی روانی۔",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Attune کے ذریعے چیٹ کریں — یہ پوری گفتگو پڑھتا ہے اور ہر اگلے پرامپٹ کو بہتر بناتا ہے۔",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "اس پوری گفتگو سے آپ کیا چاہتے ہیں؟ (اختیاری، مگر اس سے ہر پرامپٹ بہتر ہوتا ہے)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "{t} سے چیٹ لے آئیں — پوری گفتگو یا صرف آخری جواب پیسٹ کریں:",
  "Paste here…": "یہاں پیسٹ کریں…",
  "Read it & suggest my reply": "پڑھ کر میرا جواب تجویز کریں",
  "What do you want to ask? Type it however you like.": "آپ کیا پوچھنا چاہتے ہیں؟ جیسے چاہیں لکھیں۔",
  "Optimize my prompt": "میرا پرامپٹ بہتر کریں",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "طریقہ: ارادہ لکھیں ← بہتر پرامپٹ پائیں ← اسے بھیجیں ← جواب واپس لائیں ← ہر اگلا پرامپٹ زیادہ تیز۔ فون ایپ میں شیئر شیٹ کاپی پیسٹ کی جگہ لے لیتی ہے۔",
  "Ready prompt recipes — pick one, fill the blanks, then": "تیار پرامپٹ نسخے — ایک چنیں، خالی جگہیں بھریں، پھر",
