  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "مفت: سب کچھ رکھیں اور تلاش کریں۔ Pro: ہر چیز کو خود ترتیب دیتا ہے (عنوان، خلاصہ، ٹیگز)، آپ کی تصاویر پڑھتا ہے اور آپ کے ذہن سے سوالوں کے جواب دیتا ہے۔",
  "Ask your Mind": "اپنے ذہن سے پوچھیں",
