  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "اس فون پر سب کچھ رکھیں اور بیک اپ کی چیٹس، یادداشت، یاد دہانیاں اور سائیکل کے دن شامل کریں۔ پیسوں کا کھاتا بیک اپ سے تبھی لیا جاتا ہے جب اس فون پر کوئی نہ ہو۔",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "اس فون کی {c} چیٹس اور {l} کھاتے کی اندراجات بیک اپ کی چیٹس اور اندراجات سے بدل جائیں گی۔ آپ اسے ایک بار، فوراً بعد واپس کر سکتے ہیں۔",
  "The backup's items will be added to this phone. You can undo this once, right after.": "بیک اپ کی آئٹمز اس فون میں شامل کر دی جائیں گی۔ آپ اسے ایک بار، فوراً بعد واپس کر سکتے ہیں۔",
