  "No app on this phone can do that.": "اس فون کی کوئی ایپ یہ نہیں کر سکتی۔",
  "WhatsApp isn't installed — opened the share sheet instead.": "واٹس ایپ انسٹال نہیں ہے — اس کے بجائے شیئر شیٹ کھول دی۔",
