  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "تصویر بیان کریں، عربی یا انگریزی میں — مثلاً «غروبِ آفتاب کے وقت نیل پر ایک فیلوکا»",
