  "I couldn't open {f} on the phone: {why}\n\nTry saving it as .xlsx or .csv and attach it again.": "میں فون پر {f} نہیں کھول سکا: {why}\n\nاسے .xlsx یا .csv کے طور پر محفوظ کر کے دوبارہ لگائیں۔",
