  "e.g. a quick job form for the site: customer, crane, start date, days — status New": "مثلاً سائٹ کے لیے فوری کام کا فارم: گاہک، کرین، شروع کی تاریخ، دن — اسٹیٹس New",
  "Make the form": "فارم بنائیں",
