  "Save form": "فارم محفوظ کریں",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "ابھی کوئی فارم نہیں۔ فارم صرف ضروری فیلڈز آپ کی ترتیب میں تیار قدروں کے ساتھ دکھاتا ہے — ریکارڈ شامل کرتے وقت اسے چنیں۔",
