  "Updated from the app file — {n} tables with their records": "ایپ فائل سے اپ ڈیٹ ہوا — {n} ٹیبلز اپنے ریکارڈز کے ساتھ",
  "Opened — {n} tables with their records": "کھل گیا — {n} ٹیبلز اپنے ریکارڈز کے ساتھ",
  "Change the design in words — add fields to any table, new tables, links…": "ڈیزائن الفاظ میں بدلیں — کسی بھی ٹیبل میں فیلڈز، نئے ٹیبلز، لنکس…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "مثلاً Suppliers میں Email اور Tax ID شامل کریں، اور Parts میں وارنٹی کے مہینوں کی فیلڈ",
  "Saved — send this file; it opens in any browser, no Attune needed": "محفوظ ہو گیا — یہ فائل بھیجیں؛ یہ کسی بھی براؤزر میں کھلتی ہے، Attune کی ضرورت نہیں",
  "Excel files need Python, which isn't in this build — use CSV.": "Excel فائلوں کے لیے Python چاہیے جو اس بلڈ میں نہیں — CSV استعمال کریں۔",
  "Making the Excel file…": "Excel فائل بن رہی ہے…",
  "Couldn't make the Excel file: {e}": "Excel فائل نہیں بن سکی: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "اسے اپنی ٹیم کو ایپ کی طرح دیں: ایک فائل جس میں سارا ڈیٹا ہے — یہ کسی بھی فون یا کمپیوٹر کے براؤزر میں کھلتی ہے، Attune کی ضرورت نہیں۔ جب کچھ بدلنا ہو تو فائل یہاں کھولیں (بزنس ← ایپ فائل کھولیں)، AI سے کہیں، اور نئی ایپ واپس بھیج دیں۔",
  "Export as an app": "ایپ کے طور پر ایکسپورٹ کریں",
  "Excel workbook (all tables)": "Excel ورک بک (تمام ٹیبلز)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "تصویر مکمل ہونے سے پہلے تصویری انجن رک گیا — شاید Android نے میموری خالی کرنے کے لیے اسے بند کر دیا۔ «فوری ڈرافٹ» آزمائیں، یا دوسری ایپس بند کر کے دوبارہ کوشش کریں۔",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "تصویر نہیں بن سکی۔ انجن ← انجن لاگ کھولیں اور جو لکھا ہے وہ مجھے بھیجیں۔",
  "Multi-token prediction (faster writing)": "ملٹی ٹوکن پیشگوئی (تیز لکھائی)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "ڈیفالٹ طور پر بند: کچھ فونز پر یہ الفاظ اور ہندسے دہرا دیتا ہے («ItIt is is»، «20205»)۔ صرف تب آن کریں جب جواب درست رہیں۔",
  "The last picture didn't finish:": "پچھلی تصویر مکمل نہیں ہوئی:",
