  "Connect the tables": "ٹیبلز جوڑیں",
  "Something went wrong on this screen.": "اس اسکرین پر کچھ غلط ہو گیا۔",
  "Your chats and data are safe. Try again — if it keeps happening, send me this message.": "آپ کی چیٹس اور ڈیٹا محفوظ ہیں۔ دوبارہ کوشش کریں — اگر بار بار ہو تو یہ پیغام مجھے بھیجیں۔",
