  "a graphics card with 8 GB or more: the most capable model": "8 GB یا زیادہ والا گرافکس کارڈ: سب سے طاقتور ماڈل",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "سب سے طاقتور ماڈل: تصاویر میں متن، بھرے ہوئے مناظر، لوگ۔ فون پر سست (تقریباً 10 منٹ فی تصویر)، گرافکس کارڈ والے کمپیوٹر پر تیز۔ 12 GB RAM چاہیے۔",
