  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB یا زیادہ اور تیز کورز: ایک قدم میں زیادہ واضح XL ماڈل",
  "not enough free storage or speed for the XL model": "XL ماڈل کے لیے کافی خالی اسٹوریج یا رفتار نہیں",
  "the fast model fits this phone's memory": "تیز ماڈل اس فون کی میموری میں سما جاتا ہے",
  "little memory or slow cores: smaller pictures, still clear": "کم میموری یا سست کورز: چھوٹی تصاویر، پھر بھی واضح",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · تقریباً 20 سیکنڈ · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Turbo سے تیز اور زیادہ واضح، اور آپ کی بات سے بہتر مطابقت: CPU پر تقریباً 20 سیکنڈ فی تصویر۔ 512 px۔ 8 GB RAM یا زیادہ والے فونز کے لیے۔",
  "Pro · best quality": "Pro · بہترین معیار",
  "Pro on this phone's CPU: 10–20 min a picture": "اس فون کے CPU پر Pro: 10–20 منٹ فی تصویر",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "اس فون کی گرافکس چپ اسٹوڈیو کے ساتھ کام نہیں کر رہی، اس لیے Pro ماڈل CPU پر 10–20 منٹ فی تصویر لے گا۔ اسٹوڈیو Turbo تقریباً ایک منٹ میں تصویر بناتا ہے۔",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "ہر فون پر تیز تصاویر: گرافکس چپ کے بغیر تقریباً ایک منٹ، اس کے ساتھ چند سیکنڈ۔ 512 px — آئیڈیاز، ڈرافٹس اور پوسٹس کے لیے بہترین۔",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "بہترین فوٹو معیار: لوگ، جگہیں، مصنوعات اور تصاویر میں متن، 1024 px۔ آپ کی دی ہوئی تصویر میں ترمیم بھی کرتا ہے («رات بنا دو»، «گاڑی ہٹا دو»)۔ کام کرتی گرافکس چپ چاہیے — CPU پر ایک تصویر میں 10–20 منٹ لگتے ہیں۔",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "مکمل درستی کے ساتھ اسٹوڈیو Pro: باریک تفصیل، صاف چہرے، ہاتھ اور متن۔ ہدایت کے مطابق آپ کی تصاویر میں ترمیم بھی کرتا ہے۔ کام کرتی گرافکس چپ اور 12 GB RAM چاہیے۔",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "ابھی کام جاری ہے — کچھ اٹکا نہیں۔ CPU پر Turbo تقریباً 1–2 منٹ لیتا ہے۔ Attune کھلا رکھیں؛ «روکیں» اسے منسوخ کر دیتا ہے۔",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "ابھی کام جاری ہے — کچھ اٹکا نہیں۔ گرافکس چپ کے بغیر Pro تصویر میں 10–20 منٹ لگتے ہیں (ترمیم میں زیادہ)۔ رفتار کے لیے Turbo چنیں۔ Attune کھلا رکھیں؛ «روکیں» اسے منسوخ کر دیتا ہے۔",
