  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Spark کو مددگار کے طور پر ڈاؤن لوڈ کریں (تقریباً 0.5 GB، ایک بار)۔ Glow، Core اور Zenith کے ساتھ چلتا ہے۔",
