  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "سستے فون پر بھی چلتا ہے اور تصاویر پڑھتا ہے۔ مختصر جوابات اچھے؛ لمبی سوچ بچار میں اس کا سائز ظاہر ہوتا ہے۔",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "اس فون کے لیے جو اور کچھ نہیں چلا سکتا: متن کی صفائی اور مختصر کرنا۔ سوچ بچار کے لیے نہیں۔",
