  "Search tools need source + recency constraints": "سرچ ٹولز کو ذریعہ اور تازگی کی پابندی چاہیے",
  "Constraints up front prevent generic answers": "پابندیاں شروع میں بتانے سے عام جوابات نہیں آتے",
  "Active recall outperforms re-reading": "خود یاد کرنا دوبارہ پڑھنے سے بہتر ہے",
  "Sectioned output aids comprehension": "حصوں میں بٹا نتیجہ سمجھنے میں مدد دیتا ہے",
  "Explicit critique requests beat 'what do you think'": "واضح تنقید مانگنا «آپ کیا سوچتے ہیں» سے بہتر ہے",
  "Naming review axes prevents shallow feedback": "جانچ کے پہلو بتانے سے سطحی رائے نہیں آتی",
  "Include context + attempted fixes for accuracy": "درستی کے لیے سیاق اور آزمائے گئے حل شامل کریں",
  "Section-by-section output beats 'write a page'": "حصہ بہ حصہ نتیجہ «ایک صفحہ لکھو» سے بہتر ہے",
  "Persona-specific prompts improve targeting": "مخصوص شخصیت والے پرامپٹس ہدف بہتر کرتے ہیں",
  "Stating criteria prevents generic pro/con lists": "معیار بتانے سے عام فائدے/نقصان کی فہرستیں نہیں بنتیں",
  "Level-setting improves explanation fit": "سطح طے کرنے سے وضاحت موزوں ہوتی ہے",
  "Specifying length prevents rambling summaries": "لمبائی بتانے سے بے ربط خلاصے نہیں بنتے",
  "Ask to implement, not 'suggest changes' (Anthropic)": "«تبدیلیاں تجویز کرو» کے بجائے نافذ کرنے کو کہیں (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "سوچنے والے ماڈلز واضح دائرے کے ساتھ، بغیر مثالوں کے بہترین ہیں",
  "Name every state so nothing is left ambiguous": "ہر حالت کا نام لیں تاکہ کچھ مبہم نہ رہے",
  "Natural language + explicit variety works on GPT": "عام زبان + واضح تنوع GPT پر کام کرتا ہے",
  "Outcome framing beats feature lists": "نتیجہ بیان کرنا خصوصیات کی فہرست سے بہتر ہے",
  "Gemini prefers direct, constrained prompts": "Gemini سیدھے، پابند پرامپٹس پسند کرتا ہے",
  "Short + specific tone yields natural output": "مختصر + مخصوص لہجہ فطری نتیجہ دیتا ہے",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "Chain-of-thought: مشکل منطقی سوالات پر اوسطاً ~40%+ (Wei et al.)؛ MultiArith 18%→79%۔ سوچنے والے ماڈلز پر چھوڑ دیں — فائدہ کم، تاخیر زیادہ۔",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "1–5 مثالیں (few-shot) پیٹرن والے کاموں کی درستی +43% تک بڑھاتی ہیں؛ Gemini جیسے غیر سوچنے والے ماڈلز پر بہترین۔ خالص منطقی کاموں میں مثالیں نہ دیں — نقصان ہو سکتا ہے۔",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: بتائیں کہ اچھا نتیجہ کیسا ہوتا ہے؛ جدید ماڈلز پر حد سے زیادہ ہدایات شور بڑھاتی ہیں۔",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "2026 کا طریقہ: سوچنے کی شدت طے کریں (thinking/effort کنٹرول) اور الفاظ نتیجے پر خرچ کریں، «قدم بہ قدم سوچو» پر نہیں۔",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "پہلے وضاحت مانگنے سے بے کار باریاں کم ہوتی ہیں — ماڈل اندازہ لگانے کے بجائے کمی والا سیاق جمع کرتا ہے۔",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "2026 کے ماڈلز پر نتیجے کا معیار («اچھا» کیا ہے) طریقۂ کار کی ہدایات سے بہتر کام کرتا ہے۔",
  "Verification steps reduce errors on factual/analytical tasks.": "تصدیق کے مراحل حقائق اور تجزیے والے کاموں میں غلطیاں کم کرتے ہیں۔",
  "Explicit sections prevent rambling updates": "واضح حصے بے ربط اپ ڈیٹس سے بچاتے ہیں",
  "Asking for risks surfaces what you forgot": "خطرات پوچھنے سے وہ سامنے آتا ہے جو آپ بھول گئے",
  "Outcome framing keeps feedback constructive": "نتیجے پر توجہ رائے کو تعمیری رکھتی ہے",
  "Explicit audience prevents vague procedures": "واضح سامعین مبہم طریقۂ کار سے بچاتے ہیں",
  "Spaced repetition beats massed practice": "وقفے وقفے سے دہرائی ایک ساتھ رٹنے سے بہتر ہے",
  "Worked examples aid transfer to new problems": "حل شدہ مثالیں نئے مسائل پر لاگو کرنے میں مدد دیتی ہیں",
  "Planning prompts reduce rework on complex tasks": "منصوبہ بندی والے پرامپٹس پیچیدہ کاموں میں دوبارہ کام کم کرتے ہیں",
  "Explicitly requesting edge cases improves coverage": "خاص حالات واضح طور پر مانگنے سے احاطہ بہتر ہوتا ہے",
  "Specificity outperforms enthusiasm in cold outreach": "انجان لوگوں سے رابطے میں جوش سے زیادہ وضاحت کام آتی ہے",
  "Goal-anchored planning beats idea dumps": "مقصد سے جڑی منصوبہ بندی خیالات کے ڈھیر سے بہتر ہے",
  "Requesting alternatives counters fixation": "متبادل مانگنا ایک ہی خیال پر اٹکنے سے بچاتا ہے",
  "Citation requirements reduce unsupported claims": "حوالے کی شرط بے بنیاد دعوے کم کرتی ہے",
  "Grounding in supplied sources reduces hallucination; tell it to admit gaps.": "دیے گئے ذرائع پر انحصار من گھڑت باتیں کم کرتا ہے؛ کمی ماننے کو کہیں۔",
