  "Couldn't copy — press and hold the log to select it": "کاپی نہیں ہو سکا — منتخب کرنے کے لیے لاگ کو دبائے رکھیں",
  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "اسٹوڈیو پروسیسر پر تصویر بنا رہا ہے (سست)۔ اس فون میں گرافکس چپ ہے — اسے آزمائیں: وہاں تصاویر اور ×4 شارپننگ کئی گنا تیز ہیں۔",
