  "Drawing on the GPU failed twice, so Attune switched Studio to the CPU. ": "GPU پر تصویر بنانا دو بار ناکام ہوا، اس لیے Attune نے اسٹوڈیو کو CPU پر منتقل کر دیا۔",
  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "تصویری ماڈل لوڈ کرتے وقت GPU ڈرائیور دو بار اٹک گیا، اس لیے Attune نے اسٹوڈیو کو CPU پر منتقل کر دیا (آپ نیچے GPU دوبارہ آزما سکتے ہیں)۔",
  "Show only the models worth using on this device": "صرف وہ ماڈلز دکھائیں جو اس ڈیوائس پر استعمال کے قابل ہیں",
  "Combine your data": "اپنا ڈیٹا جوڑیں",
  "{t} › {f} holds {to} names ({m} of {n} found).": "{t} › {f} میں {to} کے نام ہیں ({n} میں سے {m} ملے)۔",
