  "When a column in one table names records of another (a job's customer, an invoice's crane), the phone finds it here and links them — no relationships to draw by hand.": "جب ایک ٹیبل کا کالم دوسرے ٹیبل کے ریکارڈز کا نام لیتا ہے (کام کا گاہک، انوائس کی کرین)، تو فون یہاں اسے ڈھونڈ کر جوڑ دیتا ہے — ہاتھ سے تعلقات بنانے کی ضرورت نہیں۔",
