  "Without the graphics chip, the ×4 AI sharpen takes about {m} minutes on this phone. “×2 sharper” takes a second. Start the ×4?": "گرافکس چپ کے بغیر اس فون پر ×4 AI شارپن میں تقریباً {m} منٹ لگتے ہیں۔ «×2 زیادہ واضح» ایک سیکنڈ لیتا ہے۔ ×4 شروع کریں؟",
  "Highest resolution — sharpen every picture (×4 with the graphics chip; an instant ×2 without it)": "سب سے زیادہ ریزولیوشن — ہر تصویر شارپ کریں (گرافکس چپ کے ساتھ ×4؛ اس کے بغیر فوری ×2)",
