  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "اس کے لیے کچھ نہیں ملا — علاقے کا نام بھی لکھیں (مثلاً «… New Cairo»)، یا نقشہ وہاں لے جا کر دوبارہ تلاش کریں۔",
