  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "میں نے {f}{t} کے ساتھ آپ کی گفتگو پڑھ لی (تقریباً {n} الفاظ)۔ اس بارے میں کچھ بھی پوچھیں — اسے چیک کریں، خلاصہ کریں، یا جہاں رکی تھی وہاں سے جاری رکھیں۔",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · AI آپ کی ڈیوائس پر چلتا ہے · کوئی اکاؤنٹ نہیں، کوئی سائن اِن نہیں · ویب تلاش صرف جب سوال کو ضرورت ہو (خودکار) — ویب بٹن سے بند کریں",
  "Web: Off — nothing is looked up": "ویب: بند — کچھ تلاش نہیں ہوتا",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "چیٹ میں ویب بند ہونے پر بھی قیمتوں، خصوصیات، خبروں، اسکورز یا اس سال کے بارے میں سوالات تلاش کیے جاتے ہیں (صرف تلاش کے الفاظ فون سے باہر جاتے ہیں)۔ بند: جب تک آپ ویب آن نہ کریں کچھ تلاش نہیں ہوتا۔",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "ماڈل نے بے معنی باتیں لکھیں — اسے سیف موڈ میں دوبارہ شروع کر کے پھر پوچھا جا رہا ہے…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "یہ ماڈل اس فون پر سیف موڈ میں بھی بے معنی لکھتا ہے۔ انجن میں کوئی اور ماڈل چنیں (Core اچھا چلتا ہے) اور ہمیں بتائیں کون سا ناکام ہوا۔",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "اس ماڈل کے لیے سیف موڈ آن ہے: اس نے ایک بار اس فون پر بے معنی لکھا تھا، اس لیے یہ رفتار کی ترکیبوں کے بغیر اور مکمل درستی والی میموری کے ساتھ چلتا ہے (تھوڑا سست، وہی جوابات)۔",
  "Turn safe mode off": "سیف موڈ بند کریں",
