  "Was the airline a UK one? (UK rules cover flights INTO the UK only on UK airlines)": "کیا ایئرلائن برطانوی تھی؟ (UK قوانین برطانیہ آنے والی پروازوں پر صرف برطانوی ایئرلائنز کے لیے لاگو ہوتے ہیں)",
  "Which airline was it? (Canada's amounts depend on its size)": "کون سی ایئرلائن تھی؟ (کینیڈا میں رقم اس کے سائز پر منحصر ہے)",
