  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "7–13 دن پہلے بتایا گیا: حق نہیں اگر انہوں نے ایسی فلائٹ پیش کی جو آپ کی فلائٹ سے زیادہ سے زیادہ 2 گھنٹے پہلے روانہ ہو اور زیادہ سے زیادہ 4 گھنٹے بعد پہنچے۔",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "7 دن سے کم پہلے بتایا گیا: حق صرف تب نہیں جب انہوں نے ایسی فلائٹ پیش کی جو زیادہ سے زیادہ 1 گھنٹہ پہلے روانہ ہو اور زیادہ سے زیادہ 2 گھنٹے بعد پہنچے۔",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "حق تب بنتا ہے جب تاخیر ایئرلائن کے اختیار میں ہو اور حفاظت کی وجہ سے نہ ہو۔ 1 سال کے اندر دعویٰ کریں۔",
