  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "ایک عدد اور ایک تاریخ بتائیں: جون تک 60,000 بچانا · 20 جنوری سے پہلے 6 kg کم کرنا · 1 دسمبر تک 900k سے کم میں … خریدنا · اس مہینے کھانے پر 3,000 سے زیادہ خرچ نہ کرنا · دسمبر تک احمد کا قرض اتارنا · دسمبر تک ترکی کا کورس مکمل کرنا۔",
  "Start the mission": "مشن شروع کریں",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "آپ کے پیسوں کے مشنز کو مل کر ہر مہینے {a} چاہیے، لیکن آپ تقریباً {b} بچاتے ہیں۔ ایک روک دیں، یا کوئی تاریخ آگے کریں۔",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "ابھی کوئی مشن نہیں۔ اوپر سے ایک شروع کریں — بچت کا ہدف، وزن کا ہدف، کچھ خریدنا، خرچ کی حد، قرض یا کوئی کورس۔",
