  "Where": "کہاں",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "ہر ٹول تین قدموں میں، اس کی اسکرین کی تصویر کے ساتھ — اور Attune کو اپنے دن کا حصہ بنانے کا پلان۔",
