  "Locking and uploading…": "لاک کر کے اپ لوڈ ہو رہا ہے…",
  "Type the address shown on the other device, like 192.168.1.20:41873": "دوسرے ڈیوائس پر دکھایا گیا پتہ لکھیں، جیسے 192.168.1.20:41873",
  "The code has 8 letters and numbers": "کوڈ میں 8 حروف اور ہندسے ہوتے ہیں",
