  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "اپنے فون اور کمپیوٹر (یا دو فونز) کو ایک جیسا رکھیں۔ ڈیٹا اس ڈیوائس سے نکلنے سے پہلے لاک ہو جاتا ہے؛ جو ایک پر حذف کریں وہ دوسرے پر بھی حذف ہوتا ہے، اور کچھ ضائع نہیں ہوتا۔",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "Attune کو اس Wi-Fi پر آپ کا دوسرا ڈیوائس ڈھونڈنے دیں (Android ایک بار پوچھتا ہے)۔",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "دوسرے ڈیوائس پر: بیک اپ → سنک → Wi-Fi → کنیکٹ، اور لکھیں:",
