  "Connect and sync": "کنیکٹ کر کے سنک کریں",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "آپ کی اپنی Google Drive میں ایک فائل، ایک چھپے فولڈر میں جسے صرف Attune کھول سکتا ہے۔ یہ اسی ڈیوائس پر آپ کے سنک پاس فریز سے لاک ہوتی ہے، اس لیے Google کے پاس صرف بے معنی ڈیٹا ہوتا ہے۔",
