  "Google sync on the computer comes in the next update — use Wi-Fi with your phone for now.": "کمپیوٹر پر Google سنک اگلی اپ ڈیٹ میں آئے گا — فی الحال فون کے ساتھ Wi-Fi استعمال کریں۔",
