  "Weigh yourself 2–3 times a week for two weeks and your target will follow what your body really does.": "دو ہفتے، ہفتے میں 2–3 بار وزن کریں اور آپ کا ہدف آپ کے جسم کے اصل حساب پر چلے گا۔",
  "You ate about {eaten} kcal a day and your weight held — so you burn about {burn}. Your plan now counts {tdee}.": "آپ نے روزانہ تقریباً {eaten} kcal کھائیں اور وزن ویسا رہا — تو آپ تقریباً {burn} جلاتے ہیں۔ آپ کا پلان اب {tdee} گنتا ہے۔",
  "You ate about {eaten} kcal a day and lost {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "آپ نے روزانہ تقریباً {eaten} kcal کھائیں اور ہفتے میں {kg} kg کم کیا — تو آپ تقریباً {burn} جلاتے ہیں۔ آپ کا پلان اب {tdee} گنتا ہے۔",
  "You ate about {eaten} kcal a day and gained {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "آپ نے روزانہ تقریباً {eaten} kcal کھائیں اور ہفتے میں {kg} kg بڑھایا — تو آپ تقریباً {burn} جلاتے ہیں۔ آپ کا پلان اب {tdee} گنتا ہے۔",
