  "The simulator needs at least a month of your income and spending in Money.": "سمیولیٹر کو پیسے میں کم از کم ایک مہینے کی آمدنی اور خرچ چاہیے۔",
  "Option": "آپشن",
  "Never runs out": "کبھی ختم نہیں ہوتا",
  "Cash in 1 year": "1 سال میں نقد",
  "3 years": "3 سال",
  "5 years": "5 سال",
  "Owned after 5 years": "5 سال بعد ملکیت",
  "Don't do it": "ایسا نہ کریں",
  "Stress tests: chance cash never runs out": "دباؤ ٹیسٹ: نقد کبھی ختم نہ ہونے کا امکان",
  "Median of 2,000 futures in today's {c}, from your last {d} days in Money. Installments are fixed, so inflation makes them smaller each month; savings earn the certificate rate. A model, not a promise.": "آج کے {c} میں 2,000 مستقبل کا وسطی نتیجہ، پیسے میں آپ کے پچھلے {d} دن سے۔ قسطیں مقرر ہیں، اس لیے مہنگائی انہیں ہر مہینے چھوٹا کرتی ہے؛ بچت پر سرٹیفکیٹ کی شرح ملتی ہے۔ ایک ماڈل ہے، وعدہ نہیں۔",
  "Careful: with every option, your cash runs out in more than 1 future in 10. The safest is {best} ({ok}% of futures stay above zero).": "احتیاط: ہر آپشن کے ساتھ 10 میں سے 1 سے زیادہ مستقبل میں آپ کا نقد ختم ہو جاتا ہے۔ سب سے محفوظ {best} ہے ({ok}% مستقبل صفر سے اوپر رہتے ہیں)۔",
  "{best}: {ok}% of futures never run out of cash; after 5 years you would have about {worth} (today's pounds, including what you bought).": "{best}: {ok}% مستقبل میں نقد کبھی ختم نہیں ہوتا؛ 5 سال بعد آپ کے پاس تقریباً {worth} ہوگا (آج کے پاؤنڈ میں، خریدی چیزوں سمیت)۔",
  "{best} is better: {ok}% of futures never run out of cash, and after 5 years you would have about {worth} in today's pounds — {diff} more than {other}.": "{best} بہتر ہے: {ok}% مستقبل میں نقد کبھی ختم نہیں ہوتا، اور 5 سال بعد آج کے پاؤنڈ میں تقریباً {worth} ہوگا — {other} سے {diff} زیادہ۔",
  "The answer came in English — writing it again in Arabic…": "جواب انگریزی میں آیا — عربی میں دوبارہ لکھ رہا ہوں…",
  "The answer came in the wrong language — writing it again in English…": "جواب غلط زبان میں آیا — انگریزی میں دوبارہ لکھ رہا ہوں…",
  "{n} calculations checked by code — all correct": "{n} حساب کوڈ سے چیک — سب درست",
  "Checked by code: {n} calculation(s) don't add up": "کوڈ سے چیک: {n} حساب درست نہیں بیٹھتے",
  "not": "نہیں",
  "Copy all": "سب کاپی کریں",
  "not published": "غیر شائع شدہ",
  "Message alerts": "پیغام الرٹ",
  "Tell Attune whose message you are waiting for — on WhatsApp, Gmail or any email app — and it tells you the moment it arrives. Checked on this phone; SMS only if you switch it on below.": "Attune کو بتائیں آپ کس کے پیغام کا انتظار کر رہے ہیں — WhatsApp، Gmail یا کسی بھی ای میل ایپ پر — اور وہ آتے ہی بتا دے گا۔ اسی فون پر چیک ہوتا ہے؛ SMS صرف تب جب آپ نیچے آن کریں۔",
  "Turn on Notification access for Attune so it can see new messages (Settings opens). If it is grey, see “restricted setting” in Money → Payments.": "Attune کے لیے نوٹیفکیشن رسائی آن کریں تاکہ نئے پیغامات دیکھ سکے (سیٹنگز کھلیں گی)۔ اگر گرے ہے تو پیسہ → ادائیگیاں میں «محدود سیٹنگ» دیکھیں۔",
  "e.g. tell me when Ahmed messages me": "مثلاً جب Ahmed مجھے پیغام بھیجے تو بتاؤ",
  "Say who, like: tell me when Ahmed messages me": "بتائیں کون، جیسے: جب Ahmed مجھے پیغام بھیجے تو بتاؤ",
