  "Tap 👎 on an answer in a chat with this assistant and write the right one — it becomes a rule here.": "اس اسسٹنٹ کے ساتھ چیٹ میں کسی جواب پر 👎 دبائیں اور صحیح جواب لکھیں — یہ یہاں ایک اصول بن جاتا ہے۔",
