  "Set prices first — the catalogue lists items with a price": "پہلے قیمتیں طے کریں — کیٹلاگ میں قیمت والی اشیاء آتی ہیں",
  "Your items, prices and what is in stock — as a WhatsApp message or a PDF, with an Order button that opens WhatsApp.": "آپ کی اشیاء، قیمتیں اور اسٹاک — WhatsApp پیغام یا PDF کی صورت، آرڈر بٹن کے ساتھ جو WhatsApp کھولتا ہے۔",
  "Prices or stock changed since you shared it — share the new one.": "شیئر کرنے کے بعد قیمتیں یا اسٹاک بدل گئے — نیا شیئر کریں۔",
