  "Find anything… e.g. the wifi password from a screenshot, the address Ahmed sent": "کچھ بھی ڈھونڈیں… مثلاً اسکرین شاٹ سے وائی فائی پاس ورڈ، Ahmed کا بھیجا پتہ",
  "Looking in": "کہاں دیکھا",
  "Nothing found — try other words, or fewer": "کچھ نہیں ملا — دوسرے یا کم الفاظ آزمائیں",
  "Android said no — you can allow SMS for Attune in App info.": "Android نے منع کیا — آپ ایپ انفو میں Attune کو SMS کی اجازت دے سکتے ہیں۔",
  "{n} bank messages from the last year are waiting below for you to check.": "پچھلے سال کے {n} بینک پیغامات نیچے آپ کی جانچ کے منتظر ہیں۔",
  "Bring in your old bank SMS": "اپنے پرانے بینک SMS لائیں",
  "Money starts with the last 12 months instead of today. Only bank and wallet messages; never one-time codes; nothing leaves the phone.": "پیسہ آج کے بجائے پچھلے 12 مہینوں سے شروع ہوتا ہے۔ صرف بینک اور والیٹ پیغامات؛ کبھی ون ٹائم کوڈ نہیں؛ فون سے کچھ نہیں جاتا۔",
  "Read my bank SMS": "میرے بینک SMS پڑھیں",
  "{n} emails about money read — {p} payments are waiting in Money for a tap.": "پیسے سے متعلق {n} ای میلز پڑھی گئیں — {p} ادائیگیاں پیسے میں ایک ٹیپ کی منتظر ہیں۔",
  "Gmail is connected": "Gmail جڑا ہوا ہے",
  "Read my Gmail by itself": "میرا Gmail خود پڑھیں",
  "Once a day Attune reads the new emails about money — receipts, bank alerts, subscriptions, price changes. Last read: {t}. {n} kept for Recall.": "دن میں ایک بار Attune پیسے سے متعلق نئی ای میلز پڑھتا ہے — رسیدیں، بینک الرٹ، سبسکرپشنز، قیمت میں تبدیلیاں۔ آخری بار: {t}۔ ریکال کے لیے {n} رکھی گئیں۔",
  "Receipts, bank alerts, subscriptions and price changes go to Money, the Overpaying check and Recall. Read on this phone; never one-time codes. Google asks you once.": "رسیدیں، بینک الرٹ، سبسکرپشنز اور قیمت کی تبدیلیاں پیسہ، زیادہ ادائیگی چیک اور ریکال میں جاتی ہیں۔ اسی فون پر پڑھی جاتی ہیں؛ کبھی ون ٹائم کوڈ نہیں۔ Google ایک بار پوچھے گا۔",
  "Connect Gmail": "Gmail جوڑیں",
  "Disconnect": "منقطع کریں",
  "{n} payments from Gmail are waiting in Money": "Gmail سے {n} ادائیگیاں پیسے میں منتظر ہیں",
  "Gmail isn't connected yet": "Gmail ابھی جڑا نہیں",
  "Gmail sign-in was cancelled": "Gmail سائن اِن منسوخ ہو گیا",
  "Google asks you to confirm again — tap Read now.": "Google دوبارہ تصدیق چاہتا ہے — ابھی پڑھیں دبائیں۔",
  "Attune only reads emails about money, on this phone. They never go to Attune, to an AI in the cloud or to anyone else, and are never used for ads. Disconnect any time.": "Attune صرف پیسے سے متعلق ای میلز اسی فون پر پڑھتا ہے۔ یہ کبھی Attune، کلاؤڈ کے AI یا کسی اور کو نہیں جاتیں، اور کبھی اشتہارات کے لیے استعمال نہیں ہوتیں۔ جب چاہیں منقطع کریں۔",
  "Who should it go to? Add an email address.": "یہ کسے جائے؟ ای میل پتہ شامل کریں۔",
  "You can still use Open in Gmail.": "آپ اب بھی Gmail میں کھولیں استعمال کر سکتے ہیں۔",
