  "Open in Gmail": "Gmail میں کھولیں",
  "Nothing is sent until you tap Send — here or in Gmail.": "بھیجیں دبانے تک کچھ نہیں بھیجا جاتا — یہاں یا Gmail میں۔",
  "No email app on this phone — copy the email instead.": "اس فون پر کوئی ای میل ایپ نہیں — اس کے بجائے ای میل کاپی کریں۔",
  "Keep my messages and notifications forever": "میرے پیغامات اور نوٹیفکیشنز ہمیشہ رکھیں",
  "WhatsApp, SMS, email, deliveries, banks — so you can find what someone sent, years later. Never one-time codes. Backed up with Attune's backup (Backup & restore).": "WhatsApp، SMS، ای میل، ڈیلیوریز، بینک — تاکہ برسوں بعد بھی ڈھونڈ سکیں کس نے کیا بھیجا۔ کبھی ون ٹائم کوڈ نہیں۔ Attune کے بیک اپ (بیک اپ اور بحالی) کے ساتھ بیک اپ ہوتا ہے۔",
  "{n} kept.": "{n} رکھی گئیں۔",
  "New notifications are not kept now — the ones kept stay": "نئی نوٹیفکیشنز اب نہیں رکھی جاتیں — رکھی گئی باقی رہتی ہیں",
  "Tap again to forget all {n} — this can't be undone": "تمام {n} بھلانے کے لیے دوبارہ ٹیپ کریں — یہ واپس نہیں ہو سکتا",
