  "Backs up by itself every day": "ہر روز خود بیک اپ لیتا ہے",
  "Back up by itself every day": "ہر روز خود بیک اپ لیں",
  "To {w}. Last: {t}. Everything, with Recall's messages, locked with your backup password; the newest 3 are kept.": "{w} میں۔ آخری: {t}۔ ریکال کے پیغامات سمیت سب کچھ، آپ کے بیک اپ پاس ورڈ سے لاک؛ تازہ ترین 3 رکھے جاتے ہیں۔",
  "Like WhatsApp: pick a folder once — on this phone (offline) or in Google Drive (online) — and Attune saves a locked backup there every day, messages included.": "WhatsApp کی طرح: ایک بار فولڈر چنیں — اسی فون پر (آف لائن) یا Google Drive میں (آن لائن) — اور Attune ہر روز وہاں لاک بیک اپ محفوظ کرتا ہے، پیغامات سمیت۔",
