  "Set a backup password first": "پہلے بیک اپ پاس ورڈ رکھیں",
  "Choose a backup folder first": "پہلے بیک اپ فولڈر چنیں",
  "WhatsApp groups": "WhatsApp گروپس",
  "Your groups sorted into albums with their photos — design, news, Hadith… (Chat X-Ray inside)": "آپ کے گروپس تصاویر سمیت البمز میں — ڈیزائن، خبریں، حدیث… (اندر چیٹ ایکسرے)",
  "Reading the chat…": "چیٹ پڑھ رہا ہوں…",
  "{n} new in {g}": "{g} میں {n} نئے",
  "{g}: {n} messages and photos sorted": "{g}: {n} پیغامات اور تصاویر ترتیب دی گئیں",
  "Looking at the photos… {n} left": "تصاویر دیکھ رہا ہوں… {n} باقی",
