  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "نجی: یہاں سب کچھ اسی فون پر رہتا ہے — Attune اسے کبھی اپ لوڈ نہیں کرتا، اور اس کا AI فون پر چلتا ہے۔ جوابات اور ایجنٹس صرف آپ کے سفر اور روزمرہ کی تفصیلات استعمال کرتے ہیں (کبھی پاسپورٹ، فون یا ای میل نہیں)۔ بکنگ سائٹ کو آپ کا نام، پاسپورٹ اور فون صرف تب ملتا ہے جب آپ «میری تفصیلات بھریں» دبائیں۔",
  "Use my details to make answers and agents fit me": "جوابات اور ایجنٹس کو میرے مطابق بنانے کے لیے میری تفصیلات استعمال کریں",
  "Trips and hotels": "سفر اور ہوٹل",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "جب آپ کا جملہ نہ بتائے تو ایجنٹس یہ استعمال کرتے ہیں — مثلاً ہوٹل کی نگرانی خود آپ کے ستارے ڈھونڈتی ہے۔",
  "Daily life": "روزمرہ زندگی",
