  "what exactly will be delivered": "بالکل کیا ڈیلیور ہوگا",
  "the price and when it is paid": "قیمت اور کب ادا ہوگی",
  "the deadline": "آخری تاریخ",
  "Ask for a normal deposit or a bank guarantee instead, and never sign anything blank.": "اس کے بجائے عام ڈپازٹ یا بینک گارنٹی مانگیں، اور کبھی خالی چیز پر دستخط نہ کریں۔",
  "It renews by itself — you keep paying unless you cancel in time.": "یہ خود تجدید ہوتا ہے — وقت پر منسوخ نہ کیا تو ادائیگی جاری رہتی ہے۔",
  "Ask for renewal only by written agreement, or put the cancel-by date in your Deadline Radar.": "تجدید صرف تحریری اتفاق سے مانگیں، یا منسوخی کی آخری تاریخ ڈیڈ لائن ریڈار میں ڈالیں۔",
  "Only one side can end it, or it can be ended without notice.": "صرف ایک فریق ختم کر سکتا ہے، یا بغیر نوٹس ختم ہو سکتا ہے۔",
  "Ask that both sides can end it, with the same written notice (e.g. 30 days).": "مانگیں کہ دونوں فریق یکساں تحریری نوٹس (مثلاً 30 دن) سے ختم کر سکیں۔",
  "The other side can change the terms or the price on its own.": "دوسرا فریق خود شرائط یا قیمت بدل سکتا ہے۔",
  "Ask that changes need both signatures, and that you can leave without a penalty if you don't accept them.": "مانگیں کہ تبدیلیوں کے لیے دونوں کے دستخط ہوں، اور نہ مانیں تو بغیر جرمانہ چھوڑ سکیں۔",
  "A penalty or forfeit clause — check the amount and that it applies to both sides.": "جرمانے یا ضبطی کی شق — رقم چیک کریں اور کہ یہ دونوں پر لاگو ہو۔",
  "Ask for a cap (e.g. one month's value) and the same penalty for the other side.": "حد مانگیں (مثلاً ایک مہینے کی قیمت) اور دوسرے فریق پر بھی وہی جرمانہ۔",
  "Money you pay here does not come back, even if the deal falls through.": "یہاں دیا پیسہ واپس نہیں آتا، چاہے سودا ٹوٹ جائے۔",
  "Ask that it is refunded if the other side cancels or doesn't deliver.": "مانگیں کہ دوسرا فریق منسوخ کرے یا ڈیلیور نہ کرے تو واپس ہو۔",
  "You carry all the risk, with no limit.": "سارا خطرہ آپ پر، کوئی حد نہیں۔",
  "Ask for a limit (e.g. the contract's value) and to exclude what you can't control.": "حد مانگیں (مثلاً معاہدے کی قیمت) اور جو آپ کے اختیار میں نہیں اسے خارج کرائیں۔",
  "You may not work for a competitor after you leave — check how long and where.": "چھوڑنے کے بعد شاید کسی حریف کے لیے کام نہ کر سکیں — کتنی دیر اور کہاں، چیک کریں۔",
  "Ask for 6–12 months at most, one city or field, and pay for the time it applies.": "زیادہ سے زیادہ 6–12 مہینے، ایک شہر یا شعبہ، اور اس مدت کا معاوضہ مانگیں۔",
  "Everything you make — even in your own time — would belong to them.": "جو کچھ آپ بنائیں — اپنے وقت میں بھی — ان کا ہو جائے گا۔",
  "Ask to limit it to work done for them, in work time, with their tools.": "اسے صرف ان کے لیے، کام کے وقت، ان کے آلات سے کیے کام تک محدود کرائیں۔",
  "Disputes go to arbitration or to another country's courts — this can be slow and expensive for you.": "تنازعات ثالثی یا کسی دوسرے ملک کی عدالتوں میں جاتے ہیں — یہ آپ کے لیے سست اور مہنگا ہو سکتا ہے۔",
  "Ask for the courts of your own city.": "اپنے شہر کی عدالتیں مانگیں۔",
  "You give up a right (to sue, to a refund, to object).": "آپ ایک حق چھوڑتے ہیں (مقدمہ، واپسی، اعتراض)۔",
  "Ask to delete the waiver.": "دستبرداری کی شق حذف کرائیں۔",
  "Sold as it is, with no guarantee — problems found later are yours.": "جیسا ہے ویسا فروخت، کوئی ضمانت نہیں — بعد میں ملے مسائل آپ کے۔",
  "Inspect it first (with an expert), or ask for a written guarantee period.": "پہلے معائنہ کرائیں (ماہر کے ساتھ)، یا تحریری ضمانت کی مدت مانگیں۔",
  "Secrecy that never ends.": "کبھی ختم نہ ہونے والی رازداری۔",
  "Ask for a fixed number of years (2–5 is common).": "مقررہ سال مانگیں (2–5 عام ہیں)۔",
  "They may take money from your salary — check when and how much.": "یہ آپ کی تنخواہ سے کاٹ سکتے ہیں — کب اور کتنا، چیک کریں۔",
  "Ask that deductions are only for set reasons, with a written notice and a cap.": "مانگیں کہ کٹوتی صرف طے شدہ وجوہات پر ہو، تحریری نوٹس اور حد کے ساتھ۔",
  "Ask for no more than about 1–2 % a month, and a few days' grace.": "مہینے میں تقریباً 1–2% سے زیادہ نہ مانیں، اور چند دن کی مہلت۔",
  "Ask for 5–10 % a year, written as a fixed schedule.": "سالانہ 5–10% مانگیں، مقررہ شیڈول کی صورت لکھا ہوا۔",
  "Ask for 3 months.": "3 مہینے مانگیں۔",
