  "Payment to a personal wallet or gift card — very hard to get back.": "ذاتی والیٹ یا گفٹ کارڈ میں ادائیگی — واپس لینا بہت مشکل۔",
  "They ask for a code sent to your phone — that is how accounts and wallets are stolen.": "وہ آپ کے فون پر بھیجا کوڈ مانگتے ہیں — اکاؤنٹس اور والیٹ ایسے ہی چوری ہوتے ہیں۔",
