  "Two picture models (~200 MB, once) that name the food in a photo in a few seconds — your country's dishes first — offline. They learn from the photo meals you save.": "دو تصویری ماڈل (~200 MB، ایک بار) جو چند سیکنڈ میں تصویر میں کھانے کا نام بتاتے ہیں — پہلے آپ کے ملک کے پکوان — آف لائن۔ یہ آپ کے محفوظ کردہ تصویری کھانوں سے سیکھتے ہیں۔",
  " MB": " MB",
  "Get it (~100 MB)": "لیں (~100 MB)",
  "Health Sync is installed ✓": "Health Sync انسٹال ہے ✓",
  "Install Health Sync (free trial, then a small one-time payment to its maker — not to us).": "Health Sync انسٹال کریں (مفت ٹرائل، پھر اس کے بنانے والے کو چھوٹی ایک بار ادائیگی — ہمیں نہیں)۔",
  "Open Health Sync": "Health Sync کھولیں",
  "Get Health Sync": "Health Sync لیں",
  "In Health Sync: source = Huawei Health → sign in with your Huawei ID and allow it.": "Health Sync میں: ماخذ = Huawei Health → اپنی Huawei ID سے سائن اِن کریں اور اجازت دیں۔",
  "Destination = Health Connect → allow steps, calories, distance, heart rate and exercise.": "منزل = Health Connect → قدم، کیلوریز، فاصلہ، دل کی دھڑکن اور ورزش کی اجازت دیں۔",
  "Back here: “Connect my watch”, then Refresh. The first sync can take a few minutes.": "یہاں واپس: «میری گھڑی جوڑیں»، پھر ریفریش۔ پہلی سنک میں چند منٹ لگ سکتے ہیں۔",
  "Huawei watch: Huawei Health doesn't share with Android's Health Connect by itself — the app Health Sync copies it across (once, then automatically).": "Huawei گھڑی: Huawei Health خود Android کے Health Connect سے شیئر نہیں کرتا — Health Sync ایپ اسے منتقل کرتی ہے (ایک بار، پھر خودکار)۔",
  "Open Huawei Health (let it sync the watch first)": "Huawei Health کھولیں (پہلے گھڑی کو سنک ہونے دیں)",
  "Huawei Health sent nothing — open Huawei Health once so the watch syncs, and check Attune is still allowed in Huawei Health → Me → Privacy → Data sharing.": "Huawei Health نے کچھ نہیں بھیجا — گھڑی سنک کرنے کے لیے ایک بار Huawei Health کھولیں، اور چیک کریں کہ Huawei Health → میں → پرائیویسی → ڈیٹا شیئرنگ میں Attune کو اجازت ہے۔",
  "Huawei Health wasn't allowed — tap Connect again and allow steps, calories, distance and heart rate.": "Huawei Health کو اجازت نہیں ملی — دوبارہ جوڑیں دبائیں اور قدم، کیلوریز، فاصلہ اور دل کی دھڑکن کی اجازت دیں۔",
  "Watch steps and calories work in the Android app.": "گھڑی کے قدم اور کیلوریز Android ایپ میں کام کرتے ہیں۔",
  "Huawei watch or band: connect Huawei Health directly — steps, calories, distance and heart rate, read only.": "Huawei گھڑی یا بینڈ: Huawei Health سیدھا جوڑیں — قدم، کیلوریز، فاصلہ اور دل کی دھڑکن، صرف پڑھنا۔",
  "Connect Huawei Health": "Huawei Health جوڑیں",
  "First install HMS Core (Huawei's services — free)": "پہلے HMS Core انسٹال کریں (Huawei کی سروسز — مفت)",
  "Connect your watch: steps, calories burned, workouts and heart rate go into your day automatically.": "اپنی گھڑی جوڑیں: قدم، جلائی کیلوریز، ورزشیں اور دل کی دھڑکن خود آپ کے دن میں آتے ہیں۔",
  "Through Android's Health Connect — works with Samsung Health (Galaxy Watch), Fitbit / Pixel Watch, Garmin Connect, Mi Fitness, Huawei Health (through Health Sync) and others that share to it. Read only; nothing leaves the phone.": "Android کے Health Connect کے ذریعے — Samsung Health (Galaxy Watch)، Fitbit / Pixel Watch، Garmin Connect، Mi Fitness، Huawei Health (Health Sync کے ذریعے) اور دیگر کے ساتھ کام کرتا ہے۔ صرف پڑھنا؛ فون سے کچھ نہیں جاتا۔",
  "Huawei watch?": "Huawei گھڑی؟",
  "This phone doesn't have Health Connect — install it from the Play Store (Android 9–13), or it's built into Settings on Android 14+. Phones without Google services (newer Huawei phones) can't use it.": "اس فون میں Health Connect نہیں — Play Store سے انسٹال کریں (Android 9–13)، یا Android 14+ پر سیٹنگز میں موجود ہے۔ Google سروسز کے بغیر فون (نئے Huawei فون) اسے استعمال نہیں کر سکتے۔",
  "Install Health Connect": "Health Connect انسٹال کریں",
  "Connect my watch": "میری گھڑی جوڑیں",
  "Huawei Health, through Health Sync ✓": "Huawei Health، Health Sync کے ذریعے ✓",
  "active kcal": "فعال kcal",
  "≈ worked out from your steps — your watch app didn't send its calories / distance. In Health Sync, switch on Calories and Distance too.": "≈ آپ کے قدموں سے نکالا — گھڑی کی ایپ نے کیلوریز / فاصلہ نہیں بھیجا۔ Health Sync میں کیلوریز اور فاصلہ بھی آن کریں۔",
  "Latest from the watch: ": "گھڑی سے تازہ ترین: ",
  " — open Huawei Health / Health Sync so it sends the newest steps": " — تازہ قدم بھیجنے کے لیے Huawei Health / Health Sync کھولیں",
  "Workout": "ورزش",
  "Burned calories count the watch or your logged workouts — whichever is more, never both.": "جلائی کیلوریز گھڑی یا درج ورزشوں سے گنی جاتی ہیں — جو زیادہ ہو، دونوں نہیں۔",
  "Nothing from the watch today yet — open its app once so it syncs.": "آج ابھی گھڑی سے کچھ نہیں — سنک کے لیے ایک بار اس کی ایپ کھولیں۔",
  "Matched to your watch": "آپ کی گھڑی سے ملا",
  " kcal / 1,000 steps": " kcal / 1,000 قدم",
  " m a step": " m فی قدم",
  "Match again": "دوبارہ ملائیں",
  "Numbers lower than your watch? Match it": "اعداد گھڑی سے کم؟ ملائیں",
  "Look at your watch now and type what it shows — Attune will count like your watch from now on.": "ابھی اپنی گھڑی دیکھیں اور جو دکھائے لکھیں — اب سے Attune آپ کی گھڑی کی طرح گنے گا۔",
  "kcal (Heat / Active)": "kcal (حرارت / فعال)",
