  "Polar Flow → Settings → General settings → Health Connect → on": "Polar Flow → سیٹنگز → عمومی سیٹنگز → Health Connect → آن",
  "Mi Fitness / Zepp → Profile → Health Connect (or Third-party access) → on": "Mi Fitness / Zepp → پروفائل → Health Connect (یا تھرڈ پارٹی رسائی) → آن",
  "Automatic tracking": "خودکار ٹریکنگ",
  "Connected ✓ — steps, calories burned, workouts and heart rate come into your day by themselves.": "جڑا ہوا ✓ — قدم، جلائی کیلوریز، ورزشیں اور دل کی دھڑکن خود آپ کے دن میں آتے ہیں۔",
  "Health Connect is Android's shared place for health data. Any watch app that writes to it reaches Attune. Read only; nothing leaves the phone.": "Health Connect صحت کے ڈیٹا کے لیے Android کی مشترکہ جگہ ہے۔ جو بھی گھڑی کی ایپ اس میں لکھے وہ Attune تک پہنچتی ہے۔ صرف پڑھنا؛ فون سے کچھ نہیں جاتا۔",
  "Connected ✓": "جڑا ہوا ✓",
  "Not connected yet. Opening Huawei Health is not enough: Huawei keeps the watch's data to itself, so it needs one bridge, set up once.": "ابھی جڑا نہیں۔ Huawei Health کھولنا کافی نہیں: Huawei گھڑی کا ڈیٹا اپنے پاس رکھتا ہے، اس لیے ایک پل چاہیے، ایک بار سیٹ۔",
