  "An agent checks the price twice a day and tells you when it drops — it also tracks deliveries, keeps your usual order and opens any app": "ایک ایجنٹ دن میں دو بار قیمت چیک کرتا ہے اور کم ہونے پر بتاتا ہے — یہ ڈیلیوریز ٹریک کرتا، آپ کا معمول کا آرڈر رکھتا اور کوئی بھی ایپ کھولتا ہے",
