  "Pages, documents and programs Attune made in this work. Ask for one, then tap Save on its card — it is kept here.": "اس کام میں Attune کے بنائے صفحات، دستاویزات اور پروگرام۔ ایک مانگیں، پھر اس کے کارڈ پر Save دبائیں — وہ یہاں رہے گا۔",
