  "Close this Zakāt year? Its payments become one closed year with a certificate, and a new Zakāt year starts today.": "زکوٰۃ کا یہ سال بند کریں؟ اس کی ادائیگیاں سرٹیفکیٹ کے ساتھ ایک بند سال بن جائیں گی، اور آج سے زکوٰۃ کا نیا سال شروع ہوگا۔",
  "Closed — the certificate is under Closed years": "بند ہو گیا — سرٹیفکیٹ «بند سال» میں ہے",
