  "An estimate to guide you. It uses the gold nisab (85g) and 2.5% on cash, gold, silver and money owed to you — not your home, car, or work equipment. Rulings on debts and on dropping below nisab during the year differ between scholars; confirm your case with a trusted scholar.": "رہنمائی کے لیے ایک اندازہ۔ یہ سونے کا نصاب (85 گرام) اور نقد، سونا، چاندی اور آپ کے قابلِ وصول پیسوں پر 2.5٪ لیتا ہے — آپ کے گھر، گاڑی یا کام کے سامان پر نہیں۔ قرض اور سال کے دوران نصاب سے کم ہونے کے احکام میں علما کا اختلاف ہے؛ اپنے معاملے کی تصدیق کسی معتبر عالم سے کریں۔",
