  "Welcome to Attune": "Attune میں خوش آمدید",
  "Your day, money, dates and people — organised, with an AI that runs on this phone.": "آپ کا دن، پیسہ، ملاقاتیں اور لوگ — منظم، اس فون پر چلنے والی AI کے ساتھ۔",
