  "A file locked with a family code you agree on, sent through WhatsApp or any app. No account, no server — only the people with the code can open it.": "ایک فائل جو آپ کے طے کردہ فیملی کوڈ سے بند ہے، WhatsApp یا کسی بھی ایپ سے بھیجی جاتی ہے۔ نہ اکاؤنٹ، نہ سرور — صرف کوڈ والے ہی کھول سکتے ہیں۔",
  "Sharing all of Money": "پورا پیسہ شیئر ہو رہا ہے",
