  "Choose what to share, then send the first update": "کیا شیئر کرنا ہے چنیں، پھر پہلی اپڈیٹ بھیجیں",
  "Join a share": "شیئر میں شامل ہوں",
  "Open the file someone sent you, with your family code": "کسی کی بھیجی فائل اپنے فیملی کوڈ سے کھولیں",
  "Some accounts (e.g. “House”)": "کچھ اکاؤنٹس (جیسے «گھر»)",
  "Only these are shared; everything else stays yours.": "صرف یہ شیئر ہوں گے؛ باقی آپ کا ہی رہے گا۔",
  "All of Money": "پورا پیسہ",
  "Every account and entry, with one person you trust.": "ہر اکاؤنٹ اور ہر اندراج، ایک قابلِ اعتماد شخص کے ساتھ۔",
  "Your name": "آپ کا نام",
  "Family code (6 letters or more, the same on both phones)": "فیملی کوڈ (6 حروف یا زیادہ، دونوں فون پر ایک جیسا)",
  "Open the file": "فائل کھولیں",
  "Attune reads the notifications your apps show (WhatsApp, SMS, email, Instagram, YouTube…) to plan your day: who wrote, what someone asked for at a time, what arrives today.": "Attune آپ کی ایپس کی اطلاعات (WhatsApp، SMS، ای میل، Instagram، YouTube…) پڑھتا ہے تاکہ آپ کا دن ترتیب دے: کس نے لکھا، کس نے کسی وقت کے لیے کیا مانگا، آج کیا آ رہا ہے۔",
  "They are read and kept on this phone only. Nothing is sent to us or to anyone. No account, no cloud.": "یہ صرف اسی فون پر پڑھی اور رکھی جاتی ہیں۔ ہمیں یا کسی کو کچھ نہیں بھیجا جاتا۔ نہ اکاؤنٹ، نہ کلاؤڈ۔",
  "You choose which apps count (Settings → Your day), and you can forget everything kept at any time.": "کون سی ایپس گنی جائیں یہ آپ چنتے ہیں (سیٹنگز → آپ کا دن)، اور جو رکھا ہے کسی بھی وقت مٹا سکتے ہیں۔",
  "Is this a scam?": "کیا یہ فراڈ ہے؟",
  "Paste a message, an offer or a link — or pick a screenshot. Checked on this phone; nothing is sent anywhere.": "کوئی پیغام، آفر یا لنک چسپاں کریں — یا اسکرین شاٹ چنیں۔ جانچ اسی فون پر؛ کچھ نہیں بھیجا جاتا۔",
  "e.g. “You won 5,000 EGP from InstaPay — send the code you'll receive…”": "مثلاً «آپ نے InstaPay سے 5,000 EGP جیتے — جو کوڈ آئے گا بھیجیں…»",
  "No text found in the picture": "تصویر میں کوئی تحریر نہیں ملی",
  "Whatever it says: never share a code, a card number or a password.": "جو بھی لکھا ہو: کبھی کوڈ، کارڈ نمبر یا پاس ورڈ نہ بتائیں۔",
