  "Also today:": "آج مزید:",
  "Let Attune read your notifications to plan your day": "Attune کو اپنی اطلاعات پڑھنے دیں تاکہ آپ کا دن ترتیب پائے",
  "On this phone only — nothing is sent anywhere.": "صرف اسی فون پر — کچھ نہیں بھیجا جاتا۔",
