  "In Attune: To-dos & lists → open a list → Pin to the widget": "Attune میں: کام اور فہرستیں → کوئی فہرست کھولیں → ویجٹ پر پن کریں",
  "Every box is ticked": "تمام خانوں پر نشان لگ گیا",
  "This update is from another share.": "یہ اپڈیٹ کسی دوسری شیئرنگ کی ہے۔",
  "The ledger didn't take it": "حساب کتاب نے اسے قبول نہیں کیا",
  "Open Money first": "پہلے پیسہ کھولیں",
  "This isn't a Money share.": "یہ پیسے کی شیئر فائل نہیں ہے۔",
  "They want money before you see or receive anything.": "کچھ دیکھنے یا پانے سے پہلے ہی پیسے مانگ رہے ہیں۔",
  "Payment to a personal wallet or a gift card — very hard to get back.": "ذاتی والٹ یا گفٹ کارڈ میں ادائیگی — واپس لینا بہت مشکل۔",
  "Guaranteed high profit — the sign of an investment scam.": "یقینی زیادہ منافع — سرمایہ کاری فراڈ کی علامت۔",
  "“Your account will be blocked” — banks and wallets never ask you to fix it through a message.": "«آپ کا اکاؤنٹ بند ہو جائے گا» — بینک اور والٹ کبھی پیغام کے ذریعے اسے ٹھیک کرنے کو نہیں کہتے۔",
  "They ask for your card number, PIN or password — never give these to anyone.": "وہ آپ کا کارڈ نمبر، PIN یا پاس ورڈ مانگتے ہیں — یہ کبھی کسی کو نہ دیں۔",
  "“This is my new number” followed by a request — call the person on their old number first.": "«یہ میرا نیا نمبر ہے» اور پھر کوئی مطالبہ — پہلے اس شخص کو پرانے نمبر پر فون کریں۔",
  "A parcel “held” until you pay a small fee — a common trick to get your card details.": "چھوٹی فیس دینے تک «روکا گیا» پارسل — کارڈ کی معلومات لینے کی عام چال۔",
  "Easy money for liking videos or small tasks — these end with you paying “to unlock” your earnings.": "ویڈیوز لائک کرنے یا چھوٹے کاموں پر آسان پیسہ — آخر میں کمائی «کھولنے» کے لیے آپ سے پیسے لیے جاتے ہیں۔",
  "A link that asks you to log in or confirm something.": "ایسا لنک جو لاگ ان یا کچھ تصدیق کرنے کو کہے۔",
  "The link says “{b}” but goes to {l} — not the real site.": "لنک میں «{b}» لکھا ہے مگر یہ {l} پر جاتا ہے — اصل سائٹ نہیں۔",
  "Your day from your notifications (optional)": "آپ کی اطلاعات سے آپ کا دن (اختیاری)",
  "With Notification access on, Attune reads the notifications kept on the device to plan your day: who wrote to you today, what someone asked for at a time (shown as a reminder you can add), what arrives today, and a count of other apps (Instagram, YouTube…). This happens on the device, by code; nothing is sent anywhere. Choose which apps count, or switch it off, in Settings → Your day.": "اطلاعات تک رسائی آن ہو تو Attune ڈیوائس پر رکھی اطلاعات پڑھتا ہے تاکہ آپ کا دن ترتیب دے: آج کس نے لکھا، کس نے کسی وقت کے لیے کیا مانگا (شامل کرنے کے قابل یاددہانی کے طور پر دکھایا جاتا ہے)، آج کیا آ رہا ہے، اور دوسری ایپس کی اطلاعات کی گنتی (Instagram، YouTube…)۔ یہ ڈیوائس پر، کوڈ کے ذریعے ہوتا ہے؛ کچھ بھی کہیں نہیں بھیجا جاتا۔ کون سی ایپس گنی جائیں چنیں، یا بند کریں: سیٹنگز → آپ کا دن۔",
  "Sharing Money with family (optional)": "فیملی کے ساتھ پیسہ شیئر کرنا (اختیاری)",
  "If you start a family share, Attune makes one file with only what you chose (some accounts, or all of Money), locked with a family code you agree on (AES-256), and hands it to the app you pick (WhatsApp, email…) to send. Attune has no server and never sees it; only people with the code can open it. Zakat records are never shared. Stop any time in Money → More → Share with family.": "اگر آپ فیملی شیئرنگ شروع کریں تو Attune صرف آپ کی چنی چیزوں (کچھ اکاؤنٹس یا پورا پیسہ) کی ایک فائل بناتا ہے، جو آپ کے طے کردہ فیملی کوڈ (AES-256) سے بند ہوتی ہے، اور بھیجنے کے لیے آپ کی چنی ایپ (WhatsApp، ای میل…) کو دیتا ہے۔ Attune کا کوئی سرور نہیں اور وہ اسے کبھی نہیں دیکھتا؛ صرف کوڈ والے کھول سکتے ہیں۔ زکوٰۃ کے ریکارڈ کبھی شیئر نہیں ہوتے۔ کسی بھی وقت روکیں: پیسہ → مزید → فیملی سے شیئر کریں۔",
