  "At a message's time, Attune opens that WhatsApp chat with your message written and presses Send for you.": "پیغام کے وقت Attune وہ واٹس ایپ چیٹ آپ کا پیغام لکھ کر کھولتا ہے اور آپ کی جگہ بھیجیں دباتا ہے۔",
  "It uses Android's Accessibility service only for that: only in WhatsApp, only for messages you scheduled, only when the box holds your message.": "یہ اینڈرائیڈ کی رسائی سروس صرف اسی کے لیے استعمال کرتا ہے: صرف واٹس ایپ میں، صرف آپ کے شیڈول کیے پیغامات کے لیے، صرف جب خانے میں آپ کا پیغام ہو۔",
  "It reads nothing else and sends nothing else. When the phone is locked it can't — you get the one-tap notification instead.": "یہ کچھ اور نہیں پڑھتا نہ بھیجتا ہے۔ فون لاک ہو تو نہیں کر سکتا — تب ایک ٹیپ والی اطلاع آئے گی۔",
