  "Load test report": "لوڈ ٹیسٹ رپورٹ",
  "Operator licence": "آپریٹر لائسنس",
  "Follow-ups → ⋯ → Errands. Type it once: “car licence expires 3 Feb 2027, plate أ ب ج 1234”.": "فالو اپ ← ⋯ ← کام۔ ایک بار لکھیں: «گاڑی کی رجسٹریشن 3 فروری 2027 کو ختم، نمبر أ ب ج 1234»۔",
  "Before it is due it shows under Needs you, with the papers to bring.": "تاریخ سے پہلے یہ 'آپ کی ضرورت' میں ضروری کاغذات کے ساتھ دکھے گا۔",
  "Open the official page — Attune reads what is due; you press Pay.": "سرکاری صفحہ کھولیں — Attune واجب رقم پڑھتا ہے؛ ادا آپ کرتے ہیں۔",
  "Traffic fines, bills, licences, a crane's inspection — all in one list.": "چالان، بل، لائسنس، کرین کا معائنہ — سب ایک فہرست میں۔",
  "driving licence expires 20 Nov 2026": "ڈرائیونگ لائسنس 20 نومبر 2026 کو ختم",
  "Driving licence · in 13 days": "ڈرائیونگ لائسنس · 13 دن میں",
  "“Car licence expires 3 Feb 2027”": "«گاڑی کی رجسٹریشن 3 فروری 2027 کو ختم»",
  "Told before it is due, with the papers to bring": "تاریخ سے پہلے اطلاع، کاغذات کے ساتھ",
  "Each place is one page with tabs on top — Money opens on your money, with Follow-ups next to it.": "ہر جگہ ایک صفحہ ہے جس کے اوپر ٹیبز ہیں — پیسے آپ کے پیسوں پر کھلتا ہے، ساتھ فالو اپ۔",
  "Attune puts it in the right place — Money, Reminders, People & plans, To-dos, Dates — and says what it did. Wrong? Tap Undo.": "Attune اسے صحیح جگہ رکھتا ہے — پیسے، یاد دہانیاں، لوگ اور منصوبے، کام، تاریخیں — اور بتاتا ہے کیا کیا۔ غلط؟ واپس کریں دبائیں۔",
  "One sentence does a lot: “Ahmed owes me 12,000, 1,000 a month” becomes 12 payments with a reminder before each one.": "ایک جملہ بہت کچھ کرتا ہے: «احمد پر میرے 12,000 ہیں، 1,000 ماہانہ» ہر قسط سے پہلے یاد دہانی کے ساتھ 12 ادائیگیاں بن جاتا ہے۔",
  "Type a goal with a number and a date: «عايز أوفر 60 ألف قبل يونيو», “lose 6 kg before 20 January”, a Corolla 2022 under 900,000 before 1 December. Tap Start the mission. More kinds: a spending limit («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») and a debt from Money → People («عايز أخلص دين أحمد قبل ديسمبر»).": "عدد اور تاریخ کے ساتھ ہدف لکھیں: «عايز أوفر 60 ألف قبل يونيو»، «20 جنوری سے پہلے 6 کلو کم کرنا»، 1 دسمبر سے پہلے 900,000 سے کم میں Corolla 2022۔ مشن شروع کریں دبائیں۔ اور اقسام: خرچ کی حد («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») اور پیسے ← لوگ سے ایک قرض («عايز أخلص دين أحمد قبل ديسمبر»)۔",
  "Every time Attune opens it reads your Money and the prices your agents saw, and shows your real chance (from your own past days, thousands of possible futures) and your progress.": "ہر بار کھلنے پر Attune آپ کے پیسے اور ایجنٹس کی دیکھی قیمتیں پڑھتا ہے، اور آپ کا اصل امکان (آپ کے اپنے دنوں سے، ہزاروں ممکنہ مستقبل) اور پیش رفت دکھاتا ہے۔",
  "Tools holds Writing, Files & Converter and Ask a PDF — tap one to open it.": "ٹولز میں لکھائی، فائلیں اور کنورٹر اور PDF سے پوچھیں ہیں — کھولنے کے لیے کسی پر ٹیپ کریں۔",
  "Paste once, then try another action on the same text.": "ایک بار چسپاں کریں، پھر اسی متن پر دوسرا کام آزمائیں۔",
  "Save it as:": "اس طرح محفوظ کریں:",
  "Or say how — “remind me Monday at 9”, “subscription 200 every month”": "یا بتائیں کیسے — «پیر کو 9 بجے یاد دلانا»، «ہر مہینے 200 سبسکرپشن»",
  "I couldn't read that — try “reminder tomorrow at 9” or “expense 450”": "سمجھ نہیں آیا — «کل 9 بجے یاد دہانی» یا «خرچ 450» آزمائیں",
  "If your money stays as it is, you will pay about {a} on {d} ({p}% of {b}).": "اگر آپ کا مال ایسا ہی رہا تو آپ {d} کو تقریباً {a} ادا کریں گے ({b} کا {p}%)۔",
  "If your money stays as it is, it stays under the niṣāb — no Zakāt this year.": "اگر آپ کا مال ایسا ہی رہا تو نصاب سے کم رہے گا — اس سال زکوٰۃ نہیں۔",
