  "I couldn't read classes in this photo. An Arabic or handwritten timetable needs a model marked 📷 in Engine.": "اس تصویر میں کلاسیں نہیں پڑھ سکا۔ عربی یا ہاتھ سے لکھے ٹائم ٹیبل کے لیے انجن میں 📷 والا ماڈل چاہیے۔",
