  "{n} checks in the background couldn't read the prices — {site} shows them only in a browser. Your best stays; I read them again when you tap Check now.": "پس منظر میں {n} جانچیں قیمتیں نہیں پڑھ سکیں — {site} قیمتیں صرف براؤزر میں دکھاتا ہے۔ آپ کی بہترین قیمت برقرار ہے؛ ابھی جانچیں دبانے پر میں دوبارہ پڑھوں گا۔",
