  "Each dot = one hotel on that start date. Tap a dot to see the hotel.": "ہر نقطہ = اس چیک اِن تاریخ پر ایک ہوٹل۔ ہوٹل دیکھنے کے لیے نقطے پر ٹیپ کریں۔",
