  "{t}: {p} pays it — not taken from your balance; I'll remind you on the day": "{t}: {p} ادا کرتے ہیں — آپ کے بیلنس سے نہیں کٹے گا؛ اس دن یاد دلاؤں گا",
  "Added by itself: {t}": "خود شامل ہوا: {t}",
  "{a} · every month on the {d}": "{a} · ہر مہینے {d} تاریخ کو",
  "Who pays it?": "کون ادا کرتا ہے؟",
  "Me — take it from my balance": "میں — میرے بیلنس سے کاٹیں",
