  "{a} from {acc} — tick it in People & plans when it's paid": "{a}، {acc} سے — ادائیگی پر لوگ اور منصوبے میں نشان لگائیں",
  "Nobody — just remind me": "کوئی نہیں — بس یاد دلائیں",
  "From which balance?": "کس بیلنس سے؟",
  "{t}: nobody set — I'll only remind you on the day": "{t}: طے نہیں — بس اس دن یاد دلاؤں گا",
  "Ticked — nobody's balance changes": "نشان لگ گیا — کسی کا بیلنس نہیں بدلا",
  "Ticked — {p} pays it; your balance stays the same": "نشان لگ گیا — {p} ادا کرتے ہیں؛ آپ کا بیلنس وہی",
  "{w} renews today — was it paid?": "{w} آج تجدید ہوگا — ادا ہوا؟",
  "{w} renews today — did {p} pay it?": "{w} آج تجدید ہوگا — کیا {p} نے ادا کیا؟",
  "Done — your balance stays the same": "ہو گیا — آپ کا بیلنس وہی",
  "Compare Free and Pro": "مفت اور Pro کا موازنہ کریں",
  "Sorry — Attune closed by itself last time. Your data is safe.": "معذرت — پچھلی بار Attune خود بخود بند ہو گیا۔ آپ کا ڈیٹا محفوظ ہے۔",
  "Reading Gmail by itself isn't switched on in this version yet. Until then, “{a}” or “{b}” read the same emails.": "Gmail کو خود بخود پڑھنا اس ورژن میں ابھی فعال نہیں ہے۔ تب تک “{a}” یا “{b}” وہی ای میلز پڑھتے ہیں۔",
  "You are on Free: unlimited answers, Money and Follow-ups. Pro adds agents that act for you, Chat X-Ray, deep research, reports, slides and file conversions without limits.": "آپ مفت پلان پر ہیں: لامحدود جوابات، پیسے اور فالو اپس۔ Pro میں آپ کے لیے کام کرنے والے ایجنٹ، Chat X-Ray، گہری تحقیق، رپورٹس، سلائیڈز اور بغیر حد کے فائل کنورژن شامل ہیں۔",
  "At what price should I tell you about {w}? Write the number — e.g. 9,000": "{w} کے بارے میں کس قیمت پر بتاؤں؟ عدد لکھیں — مثلاً 9,000",
  "Tap ☰ at the top to open the sidebar (on a computer it is always on the left): Home, then To-dos & lists, Money, Follow-ups, Health and Agents, then My things, Go, Tools and Projects.": "سائیڈبار کھولنے کے لیے اوپر ☰ پر ٹیپ کریں (کمپیوٹر پر یہ ہمیشہ ایک طرف رہتی ہے): ہوم، پھر کام اور فہرستیں، پیسے، فالو اپس، صحت اور ایجنٹس، اس کے بعد میری چیزیں، چلیں، ٹولز اور پروجیکٹس۔",
  "Each place is one page — Follow-ups keeps People & plans, Reminders and Dates together; My things keeps your notes, documents, people and Mind.": "ہر جگہ ایک ہی صفحہ ہے — فالو اپس میں لوگ اور پلان، یاد دہانیاں اور تاریخیں ساتھ رہتے ہیں؛ میری چیزیں آپ کے نوٹس، دستاویزات، لوگ اور ذہن رکھتا ہے۔",
  "At the very bottom: How to use Attune, Engine, Backup and Settings. Back always takes you to the page before.": "سب سے نیچے: Attune کیسے استعمال کریں، انجن، بیک اپ اور سیٹنگز۔ واپس ہمیشہ پچھلے صفحے پر لے جاتا ہے۔",
  "Type or say what happened in the Home box: “spent 150 on lunch”, “Ahmed owes me 500”, “remind me tomorrow at 9”.": "ہوم کے خانے میں جو ہوا وہ لکھیں یا بولیں: “دوپہر کے کھانے پر 150 خرچ کیے”، “احمد پر میرے 500 باقی ہیں”، “کل 9 بجے یاد دلانا”۔",
  "Under the box: Add a to-do or a list, the cards for Money & Follow-ups and Agents, then Your day — what is waiting today, in order.": "خانے کے نیچے: کام یا فہرست شامل کریں، پیسے اور فالو اپس اور ایجنٹس کے کارڈ، پھر آپ کا دن — آج جو منتظر ہے، ترتیب سے۔",
  "Documents & memory": "دستاویزات اور یادداشت",
