  "A full-screen timer for one task; the time is kept per task": "ایک کام کے لیے فل اسکرین ٹائمر؛ وقت ہر کام کا الگ رکھا جاتا ہے",
  "Tap “+ Habit” under the Home box (or say “open habits”): a name, and its days — none picked means every day.": "ہوم باکس کے نیچے “+ عادت” دبائیں (یا کہیں “عادتیں کھولو”): نام اور اس کے دن — کوئی دن نہ چنیں تو ہر دن۔",
  "Each day, tap today's dot on the Habits card. The streak only counts the days the habit is due, so a day off never breaks it.": "ہر دن عادتوں کے کارڈ پر آج کا نقطہ دبائیں۔ لگاتار گنتی صرف مقررہ دنوں کی ہوتی ہے، اس لیے چھٹی کا دن اسے نہیں توڑتا۔",
  "Tap a habit's name to edit or remove it.": "ترمیم یا ہٹانے کے لیے عادت کے نام پر دبائیں۔",
  "Tap “+” in the chips under the Home box: pick an icon, a name and the date.": "ہوم باکس کے نیچے بٹنوں میں “+” دبائیں: ایک نشان، نام اور تاریخ چنیں۔",
  "The chip shows the days left; tap it for the big card with Edit and Remove. On the day itself it says Today.": "بٹن باقی دن دکھاتا ہے؛ ترمیم اور ہٹانے والے بڑے کارڈ کے لیے اسے دبائیں۔ اسی دن وہ آج لکھتا ہے۔",
  "With prayer times on, Ramadan shows by itself.": "نماز کے اوقات آن ہوں تو رمضان خود دکھتا ہے۔",
  "Open To-dos & lists → Plan my week. Add each task with its hours and the day it is due.": "کام اور فہرستیں → میرا ہفتہ پلان کریں کھولیں۔ ہر کام اس کے گھنٹوں اور آخری دن کے ساتھ شامل کریں۔",
  "Attune places them in your hours, around your reminders (and prayer times when they are on). Tap Keep plan to turn the blocks into reminders.": "Attune انہیں آپ کے اوقات میں، یاد دہانیوں (اور آن ہوں تو نماز) سے ہٹ کر رکھتا ہے۔ بلاکس کو یاد دہانیاں بنانے کے لیے منصوبہ رکھیں دبائیں۔",
  "A task that can't fit before its deadline is said plainly — never squeezed in.": "جو کام آخری تاریخ سے پہلے نہیں سماتا، اسے صاف بتایا جاتا ہے — ٹھونسا نہیں جاتا۔",
  "Tap ◷ next to a to-do on Home, or say “open focus” and type the task. Pick 15, 25, 50 or 90 minutes.": "ہوم پر کسی کام کے پاس ◷ دبائیں، یا کہیں “توجہ کھولو” اور کام لکھیں۔ 15، 25، 50 یا 90 منٹ چنیں۔",
  "Pause whenever you need — paused time isn't counted. Stop shows the time you really focused, kept for that task.": "جب چاہیں روکیں — رکا ہوا وقت نہیں گنا جاتا۔ بند کریں اصل توجہ کا وقت دکھاتا ہے، اس کام کے لیے محفوظ۔",
  "It's a normal Attune screen — no special permission.": "یہ Attune کی عام اسکرین ہے — کوئی خاص اجازت نہیں۔",
  "Set a goal (optional) — “21 days” — and the card shows how far you are.": "ایک ہدف رکھیں (اختیاری) — “21 دن” — اور کارڈ دکھاتا ہے آپ کہاں تک پہنچے۔",
  "Or say “open countdowns” in Chat or the Home box to add one.": "یا شامل کرنے کے لیے چیٹ یا ہوم باکس میں “الٹی گنتی کھولو” کہیں۔",
  "‹ › shows the rest of the week. Your own things are grey, prayers green, Attune's blocks in colour.": "‹ › باقی ہفتہ دکھاتے ہیں۔ آپ کی چیزیں سرمئی، نماز سبز، Attune کے بلاک رنگین۔",
  "“Well done” shows the time kept and this week's total for that task.": "“شاباش” محفوظ وقت اور اس کام کا اس ہفتے کا کل دکھاتا ہے۔",
  "New ads to check for “{t}” — tap and Attune shows only the ones that really match.": "“{t}” کے لیے جانچنے کو نئے اشتہار — دبائیں، Attune صرف واقعی میل کھانے والے دکھائے گا۔",
